fun containsDuplicate(values: List<String>): Boolean {
    val seen = mutableSetOf<String>()
    for (value in values) {
        if (!seen.add(value)) return true
    }
    return false
}

fun indexById(expenses: List<Expense>): Map<ExpenseId, Expense> {
    require(expenses.map { it.id }.toSet().size == expenses.size) {
        "Duplicate expense id"
    }
    return expenses.associateBy { it.id }
}

